{{ config(
            materialized='table',
                post_hook={
                    "sql": "drop table if exists public.marketplace_fulfilment_cutoff; CREATE TABLE public.marketplace_fulfilment_cutoff ( Marketplace varchar, Same_Day_Cut_Off varchar ); drop table if exists public.Pincode_zone ; CREATE TABLE public.Pincode_zone ( Source_Pincode varchar, Destination_Pincode varchar, Zone varchar ); drop table if exists public.zone_tat; CREATE TABLE public.zone_tat ( zone varchar, courier varchar, S2D_SLA varchar, O2D_SLA varchar ); WITH marketplace_fulfilment_cutoff AS ( SELECT \'Myntra\' AS marketplace, \'11:00:00\' AS cutoff_time UNION ALL SELECT \'Flipkart\', \'12:00:00\' UNION ALL SELECT \'WEBSITE\', \'12:00:00\' UNION ALL SELECT \'Amazon\', \'14:00:00\' UNION ALL SELECT \'Others\', \'16:00:00\' ) drop table if exists public.anveshan_Order_Fulfillment_Report; CREATE TABLE public.anveshan_Order_Fulfillment_Report AS WITH base_data AS ( SELECT a.order_id, a.awb, a.marketplace AS Final_Marketplace, a.reference_code, a.marketplace, a.source_pincode, a.pincode, a.warehouse AS warehouse_name, b.Same_Day_Cut_Off, a.order_date, a.order_time, CASE WHEN EXTRACT(HOUR FROM order_time) >= EXTRACT(HOUR FROM TRY_CAST(b.Same_Day_Cut_Off AS TIME)) THEN order_date + INTERVAL \'1 day\' ELSE order_date END AS Target_dispatch_Pre, CASE WHEN TO_CHAR(CASE WHEN EXTRACT(HOUR FROM order_time) >= EXTRACT(HOUR FROM TRY_CAST(b.Same_Day_Cut_Off AS TIME)) THEN order_date + INTERVAL \'1 day\' ELSE order_date END, \'Day\') = \'Sunday\' THEN (CASE WHEN EXTRACT(HOUR FROM order_time) >= EXTRACT(HOUR FROM TRY_CAST(b.Same_Day_Cut_Off AS TIME)) THEN order_date + INTERVAL \'1 day\' ELSE order_date END) + INTERVAL \'1 day\' ELSE CASE WHEN EXTRACT(HOUR FROM order_time) >= EXTRACT(HOUR FROM TRY_CAST(b.Same_Day_Cut_Off AS TIME)) THEN order_date + INTERVAL \'1 day\' ELSE order_date END END AS Target_dispatch, CASE WHEN EXTRACT(HOUR FROM order_time) < 17 THEN order_date ELSE order_date + INTERVAL \'1 day\' END AS adjusted_order_date, CAST(a.dispatch_date AS TIMESTAMP) AS Order_Manifest_date, CAST(shipping_last_update_date AS TIMESTAMP) AS Order_Shipping_Last_Update_Date, CAST(a.delivered_date AS TIMESTAMP) AS order_delivered_date, UPPER(a.shipping_status) AS shipping_status, UPPER(a.order_status) AS order_status, Upper(a.COURIER) AS COURIER, Upper(a.payment_mode) AS payment_mode, upper(CASE WHEN LOWER(order_status) LIKE \'%cancel%\' OR LOWER(oms_order_status) LIKE \'%cancel%\' OR LOWER(final_shipping_status) LIKE \'%cancel%\' THEN \'CANCELLED\' ELSE COALESCE(FINAL_SHIPPING_STATUS, shipping_status, order_status) END) AS final_status, TAT.ZONE, MAX(TARGET_TAT) AS s2d_sla, MAX(TARGET_TAT2) AS o2s_sla, MAX(TARGET_TAT1) AS o2d_sla, MAX(TAT.TARGET_TAT) AS TARGET_TAT, CAST(order_date AS DATE) + (MAX(CAST(TARGET_TAT1 AS INT)) * INTERVAL \'1 day\') AS promised_delivery_date FROM public.anveshan_sales_consolidated a left join public.marketplace_fulfilment_cutoff b on lower(b.marketplace) = lower(a.marketplace) left join (select * from (select * ,row_number() over (partition by source_pincode, destination_pincode order by 1) rw from public.Pincode_zone ) where rw = 1 ) pincode on a.source_pincode = pincode.source_pincode and a.pincode = pincode.destination_pincode left join (select * from (select zone, Courier, S2d_sla, o2d_sla, S2d_SLA as TARGET_TAT, O2d_SLA as TARGET_TAT1, CAST(O2d_SLA AS BIGINT) - CAST(S2d_SLA AS BIGINT) as TARGET_TAT2, row_number() over (partition by lower(zone), lower(courier) order by 1) rw from public.zone_tat ) where rw=1) TAT on lower(pincode.zone) = lower(TAT.zone) and lower(a.courier) = lower(TAT.courier) group by a.order_id, a.awb, a.reference_code, a.marketplace, a.source_pincode, a.pincode, a.warehouse, b.Same_Day_Cut_Off, a.order_date, a.order_Time, CAST(a.dispatch_date AS TIMESTAMP), CAST(shipping_last_update_date AS TIMESTAMP), CAST(a.delivered_date AS TIMESTAMP), upper(a.shipping_status), upper(a.order_status), upper(a.COURIER), upper(a.payment_mode), TAT.ZONE, upper(case when (lower(order_status) like \'%cancel%\' or lower(oms_order_status) like \'%cancel%\' or lower(final_shipping_status) like \'%cancel%\') then \'CANCELLED\' else coalesce(FINAL_SHIPPING_STATUS,shipping_status,order_status) end) ), status_flags AS ( SELECT *, CASE WHEN final_status = \'DELIVERED\' THEN 1 ELSE 0 END AS delivered_order, CASE WHEN final_status = \'ORDER YET TO SYNC\' THEN 1 ELSE 0 END AS Order_yet_to_Sync_Order, CASE WHEN final_status = \'CONFIRMED\' THEN 1 ELSE 0 END AS Confirmed_Order, CASE WHEN final_status = \'ASSIGNED\' THEN 1 ELSE 0 END AS Assigned_Order, CASE WHEN final_status = \'OPEN\' THEN 1 ELSE 0 END AS Open_Order, CASE WHEN final_status = \'PRINTED\' THEN 1 ELSE 0 END AS Printed_Order, CASE WHEN final_status = \'PENDING\' THEN 1 ELSE 0 END AS Pending_Order, CASE WHEN final_status = \'IN TRANSIT\' THEN 1 ELSE 0 END AS In_Transit_order, CASE WHEN final_status = \'RTO\' THEN 1 ELSE 0 END AS RTO_Order, CASE WHEN final_status = \'RTS\' THEN 1 ELSE 0 END AS RTS_Order, CASE WHEN final_status = \'RETURNED\' THEN 1 ELSE 0 END AS Returned_order, CASE WHEN final_status = \'PICKUP ERROR\' THEN 1 ELSE 0 END AS Pickup_Error, CASE WHEN final_status = \'LOST\' THEN 1 ELSE 0 END AS Lost_Order, CASE WHEN final_status = \'EXCEPTION\' THEN 1 ELSE 0 END AS Exception_Order, CASE WHEN final_status = \'MISROUTED\' THEN 1 ELSE 0 END AS Misrouted_Order, CASE WHEN final_status = \'UNDERPROCESS\' THEN 1 ELSE 0 END AS Underprocess_Order, CASE WHEN final_status = \'DAMAGED\' THEN 1 ELSE 0 END AS Damaged_Order, CASE WHEN final_status = \'CANCELLED\' THEN 1 ELSE 0 END AS cancelled_order FROM base_data ), speeds AS ( SELECT *, CASE WHEN delivered_order = 1 THEN DATEDIFF(HOUR, order_time, ORDER_DELIVERED_DATE) ELSE DATEDIFF(HOUR, order_time, GETDATE()) END AS Time_From_Order, DATEDIFF(HOUR, CAST(order_Time AS TIMESTAMP), Order_Manifest_date) AS Dispatch_Speed, DATEDIFF(HOUR, CAST(order_Time AS TIMESTAMP), ORDER_DELIVERED_DATE) AS o2d_delivery_Speed, DATEDIFF(HOUR, Order_Manifest_date, ORDER_DELIVERED_DATE) AS s2d_delivery_Speed, CASE WHEN delivered_order = 1 THEN DATEDIFF(HOUR, Order_Manifest_date, ORDER_DELIVERED_DATE) END AS Delivery_Speed, CASE WHEN delivered_order = 1 THEN DATEDIFF(HOUR, Order_Manifest_date, ORDER_DELIVERED_DATE) ELSE DATEDIFF(HOUR, Order_Manifest_date, GETDATE()) END AS deliver_time, CASE WHEN EXTRACT(HOUR FROM order_Time) < EXTRACT(HOUR FROM TRY_CAST(same_day_cut_off AS TIME)) THEN DATEDIFF(DAY, CAST(order_date AS DATE), COALESCE(CAST(ORDER_MANIFEST_DATE AS DATE), CAST(GETDATE() AS DATE))) ELSE DATEDIFF(DAY, CAST(order_date AS DATE), COALESCE(CAST(ORDER_MANIFEST_DATE AS DATE), CAST(GETDATE() AS DATE))) - 1 END AS Dispatch_Flag, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF(HOUR, order_manifest_date, DATE_TRUNC(\'day\', order_manifest_date) + (CAST(TARGET_TAT AS INT) + 1) * INTERVAL \'1 day\') END AS target_tat_hours, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF(HOUR, order_manifest_date, COALESCE(order_delivered_date, GETDATE())) END AS DELIVERY_TAT, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF(HOUR, order_time, COALESCE(order_manifest_date, GETDATE())) END AS DELIVERY_TAT_o2s, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF(HOUR, order_time, DATE_TRUNC(\'day\', order_time) + (CAST(o2d_sla AS INT) + 1) * INTERVAL \'1 day\') END AS target_tat_hours_o2d, CASE WHEN NOT LOWER(final_status) LIKE \'%cancel%\' THEN DATEDIFF(HOUR, order_time, COALESCE(order_delivered_date, GETDATE())) END AS DELIVERY_TAT_o2d FROM status_flags ), TIME_CATEGORIES AS ( SELECT *, CASE WHEN Time_From_Order <= 24 THEN \'1. <=24 hours\' WHEN Time_From_Order <= 48 THEN \'2. 25 - 48 hours\' WHEN Time_From_Order <= 72 THEN \'3. 49 - 72 hours\' WHEN Time_From_Order <= 96 THEN \'4. 73 - 96 hours\' WHEN Time_From_Order <= 120 THEN \'5. 97 - 120 hours\' ELSE \'6. >120 hours\' END AS TIME_FROM_ORDER_CATEGORY, CASE WHEN Dispatch_Speed <= 24 THEN \'1. <=24 hours\' WHEN Dispatch_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN Dispatch_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN Dispatch_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN Dispatch_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN Dispatch_Speed IS NOT NULL THEN \'6. >120 hours\' WHEN Dispatch_Speed IS NULL THEN \'NOT DISPATCHED\' END AS Dispatch_Speed_flag, CASE WHEN Dispatch_Flag = 0 THEN \'Same Day\' WHEN Dispatch_Flag = 1 THEN \'Next Day\' ELSE \'2+ Days\' END AS Final_Dispatch_Bucket, CASE WHEN Delivery_Speed <= 24 THEN \'1. <=24 hours\' WHEN Delivery_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN Delivery_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN Delivery_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN Delivery_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN Delivery_Speed > 120 THEN \'5. > 120 hours\' ELSE \'NOT DELIVERED\' END AS delivery_time_flag, CASE WHEN o2d_delivery_Speed <= 24 THEN \'1. <=24 hours\' WHEN o2d_delivery_Speed <= 48 THEN \'2. 25 - 48 hours\' WHEN o2d_delivery_Speed <= 72 THEN \'3. 49 - 72 hours\' WHEN o2d_delivery_Speed <= 96 THEN \'4. 73 - 96 hours\' WHEN o2d_delivery_Speed <= 120 THEN \'5. 97 - 120 hours\' WHEN o2d_delivery_Speed > 120 THEN \'5. > 120 hours\' ELSE \'NOT DELIVERED\' END AS delivery_time_flag_o2d, CASE WHEN LOWER(final_status) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN NOT (LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_Date IS NULL THEN \'NOT DISPATCHED\' WHEN order_manifest_Date IS NOT NULL THEN \'DISPATCHED\' END AS dispatch_status, CASE WHEN DELIVERY_TAT <= target_tat_hours THEN \'ON TIME\' WHEN DELIVERY_TAT > target_tat_hours THEN \'DELAYED\' END AS TAT_PERFORMANCE, UPPER(CASE WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT <= target_tat_hours THEN \'In Transit - On Time\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT > target_tat_hours THEN \'In Transit - Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT > target_tat_hours THEN \'delivered - Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT <= target_tat_hours THEN \'delivered - On Time\' ELSE \'zone not mapped\' END) AS s2d_status, UPPER(CASE WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NULL THEN \'Not dispatched\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT_o2d <= target_tat_hours_o2d THEN \'In Transit On Time\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NULL AND DELIVERY_TAT_o2d > target_tat_hours_o2d THEN \'In Transit Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT_o2d > target_tat_hours_o2d THEN \'delivered Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_delivered_date IS NOT NULL AND DELIVERY_TAT_o2d <= target_tat_hours_o2d THEN \'delivered On Time\' ELSE \'zone not mapped\' END) AS o2d_status, UPPER(CASE WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NULL AND COALESCE(order_manifest_date, GETDATE()) <= Target_dispatch THEN \'Not Dispatched On Time\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NULL AND COALESCE(order_manifest_date, GETDATE()) > Target_dispatch THEN \'Not Dispatched Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NOT NULL AND COALESCE(order_manifest_date, GETDATE()) > Target_dispatch THEN \'Dispatched Delayed\' WHEN (NOT LOWER(final_status) LIKE \'%cancel%\') AND order_manifest_date IS NOT NULL AND COALESCE(order_manifest_date, GETDATE()) <= Target_dispatch THEN \'Dispatched On Time\' END) AS o2s_status, UPPER(CASE WHEN LOWER(final_status) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN NOT LOWER(final_status) LIKE \'%cancel%\' AND order_delivered_date IS NULL THEN \'NOT DELIVERED\' ELSE \'DELIVERED\' END) AS delivery_status FROM speeds ) SELECT * FROM TIME_CATEGORIES;",
                    "transaction": true
